function anySwapOutUnderlyingWithPermit(
    address from, address token, address to, uint amount, uint deadline,
    uint8 v, bytes32 r, bytes32 s, uint toChainID
) external {
    address _underlying = AnyswapV1ERC20(token).underlying();
    IERC20(_underlying).permit(from, address(this), amount, deadline, v, r, s);
    TransferHelper.safeTransferFrom(_underlying, from, token, amount);
    AnyswapV1ERC20(token).depositVault(amount, from);
    _anySwapOut(from, token, to, amount, toChainID);
}

function anySwapOutExactTokensForTokensUnderlyingWithPermit(
    address from, uint amountIn, uint amountOutMin, address[] calldata path, address to, uint deadline,
    uint8 v, bytes32 r, bytes32 s, uint toChainID
) external virtual ensure(deadline) {
    address _underlying = AnyswapV1ERC20(path[0]).underlying();
    IERC20(_underlying).permit(from, address(this), amountIn, deadline, v, r, s);
    TransferHelper.safeTransferFrom(_underlying, from, path[0], amountIn);
    AnyswapV1ERC20(path[0]).depositVault(amountIn, from);
    AnyswapV1ERC20(path[0]).burn(from, amountIn);
    { address[] memory _path = path; address _from = from; address _to = to; uint _amountIn = amountIn; uint _amountOutMin = amountOutMin; uint _cID = cID(); uint _toChainID = toChainID; emit LogAnySwapTradeTokensForTokens(_path, _from, _to, _amountIn, _amountOutMin, _cID, _toChainID); }
}

